{
  "scenario_title": "Weekly health insurance claim turnaround times and closed claim volumes across four regional processing centers in 2023",
  "data_context": "The claims operations excellence team collected weekly adjudication cohort performance metrics across four regional processing centers throughout 2023. The initiative aimed to monitor turnaround times, closed claim throughput, and first-pass accuracy following operational updates.",
  "script": "dim(\"processing_center\", [\"Apex Operations\", \"Summit Claims\", \"Harbor Processing\", \"Pinnacle Center\"], weights=[0.30, 0.25, 0.25, 0.20], group=\"facility\")\ndim(\"claim_type\", [\"Inpatient Medical\", \"Outpatient Care\", \"Specialty Pharmacy\"], weights=[0.35, 0.45, 0.20], group=\"service\")\ndim(\"complexity_level\", [\"Standard\", \"High Complexity\"], weights=[0.70, 0.30], ordered=\"ordinal\", group=\"complexity\")\n\ntime(\"report_week\", start=\"2023-01-02\", end=\"2023-12-25\", freq=\"weekly\")\n\nmeasure(\"turnaround_days\", \"gamma(4.0, 1.5) + {\\\"Apex Operations\\\": -1.5, \\\"Summit Claims\\\": 1.2, \\\"Harbor Processing\\\": 0.4, \\\"Pinnacle Center\\\": -0.8}[processing_center] + {\\\"Inpatient Medical\\\": 3.5, \\\"Outpatient Care\\\": -0.5, \\\"Specialty Pharmacy\\\": 1.0}[claim_type] + 2.4 * [complexity_level=High Complexity] - 0.008 * report_week\", unit=\"days\", additive=True)\nmeasure(\"claims_closed\", \"poisson(140) + {\\\"Apex Operations\\\": 35, \\\"Summit Claims\\\": -25, \\\"Harbor Processing\\\": 10, \\\"Pinnacle Center\\\": 0}[processing_center] + {\\\"Inpatient Medical\\\": -30, \\\"Outpatient Care\\\": 45, \\\"Specialty Pharmacy\\\": -15}[claim_type]\", unit=\"claims\", additive=True)\nmeasure(\"clean_claim_rate\", \"clip(0.88 - 0.015 * turnaround_days + 0.06 * [complexity_level=Standard] + gaussian(0, 0.03), 0.45, 0.99)\", unit=\"percent\", additive=False)\n\nemit(360)",
  "intents": [
    {
      "sentence": "Compare average turnaround time across processing centers",
      "columns": [
        "processing_center",
        "turnaround_days"
      ],
      "aggregate": "AVG",
      "family": "comparison"
    },
    {
      "sentence": "Track the weekly trend of average claim turnaround duration throughout the year",
      "columns": [
        "report_week",
        "turnaround_days"
      ],
      "aggregate": "AVG",
      "family": "trend"
    },
    {
      "sentence": "Total claims closed across claim types",
      "columns": [
        "claim_type",
        "claims_closed"
      ],
      "aggregate": "SUM",
      "family": "composition"
    },
    {
      "sentence": "Assess the relationship between turnaround time and clean claim rate",
      "columns": [
        "turnaround_days",
        "clean_claim_rate"
      ],
      "aggregate": "NONE",
      "family": "relation"
    }
  ]
}
